+    int num_tiles = input_tiles.size(0);
+
+    TORCH_CHECK_DTYPE(temp_costs, kFloat);
+    TORCH_CHECK_DIM(temp_costs, 3);
+    TORCH_CHECK_SIZE(temp_costs, 1, 2);
